import { Component, Show, splitProps } from "solid-js";
import { JSX } from "solid-js/jsx-runtime";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { useImageCache } from "#core/ui-next/components/image-cache.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface OrnateCardProps extends JSX.HTMLAttributes<HTMLDivElement> {
	iconSrc?: string;
	iconElement?: JSX.Element;
	/** Allows authors to specify elements that will be drawn after the rest of the ornate card elements */
	childrenInFront?: JSX.Element;
}

export interface MinimalCardProps extends JSX.HTMLAttributes<HTMLDivElement> {
	iconElement?: JSX.Element;
	isBright?: boolean;
}

const OrnateCardSymbol = Symbol();
const OrnateCardComponent: Component<OrnateCardProps> = (props) => {
	const [local, other] = splitProps(props, ["iconSrc", "iconElement", "childrenInFront", "class", "children"]);

	const images = {
		CornerAdornment: "blp:mp_player_detail",
	};

	const imageCache = useImageCache();
	imageCache.registerImages(OrnateCardSymbol, Object.values(images));

	const CornerAdornmentCSS = `url(${images.CornerAdornment})`;

	return (
		<div
			{...other}
			class={`ornate-card-bg relative ${local.iconSrc != undefined ? "mt-7" : "pt-2"} ${local.class ?? ""}`}
			data-name="Ornate-Card"
		>
			<div
				class="absolute top-4 left-1 rotate-180 size-4 bg-contain"
				style={{ "background-image": CornerAdornmentCSS }}
			/>
			<div
				class="absolute top-4 right-1 -rotate-90 size-4 bg-contain"
				style={{ "background-image": CornerAdornmentCSS }}
			/>
			<div
				class="absolute bottom-1 left-1 rotate-90 size-4 bg-contain"
				style={{ "background-image": CornerAdornmentCSS }}
			/>
			<div
				class="absolute bottom-1 right-1 size-4 bg-contain"
				style={{ "background-image": CornerAdornmentCSS }}
			/>
			{local.children}
			<Show
				when={local.iconSrc}
				fallback={<Show when={local.iconElement}>{local.iconElement}</Show>}
			>
				<Icon
					class="size-12 absolute -top-6 self-center"
					name={local.iconSrc}
				/>
			</Show>
			{local.childrenInFront}
		</div>
	);
};

export const OrnateCard = ComponentRegistry.register({
	name: "OrnateCard",
	createInstance: OrnateCardComponent,
});

const MinimalOrnateCardSymbol = Symbol();
const MinimalOrnateCardComponent: Component<MinimalCardProps> = (props) => {
	const [local, other] = splitProps(props, ["iconElement", "isBright", "class", "children"]);

	const images = {
		CornerAdornmentCSS: "url(blp:mp_player_detail)",
	};

	const imageCache = useImageCache();
	imageCache.registerImages(MinimalOrnateCardSymbol, Object.values(images));

	return (
		<div
			{...other}
			class={`${local.isBright ? "minimal-card-bg-bright" : "minimal-card-bg"} relative ${local.class ?? ""}`}
			data-name="Minimal-Card"
		>
			<div
				class="absolute top-1 left-1 rotate-180 size-4 bg-contain opacity-50"
				style={{ "background-image": images.CornerAdornmentCSS }}
			/>
			<div
				class="absolute top-1 right-1 -rotate-90 size-4 bg-contain opacity-50"
				style={{ "background-image": images.CornerAdornmentCSS }}
			/>
			<div
				class="absolute bottom-1 left-1 rotate-90 size-4 bg-contain opacity-50"
				style={{ "background-image": images.CornerAdornmentCSS }}
			/>
			<div
				class="absolute bottom-1 right-1 size-4 bg-contain opacity-50"
				style={{ "background-image": images.CornerAdornmentCSS }}
			/>
			{local.children}
			<Show when={local.iconElement}>{local.iconElement}</Show>
		</div>
	);
};

export const MinimalOrnateCard = ComponentRegistry.register({
	name: "MinimalOrnateCard",
	createInstance: MinimalOrnateCardComponent,
});
